#include "stm32f7xx.h"

void SystemClock_Config(void);

int main(void) {
  HAL_Init();
  SystemClock_Config();

  RCC->AHB1ENR |= RCC_AHB1ENR_GPIOIEN | RCC_AHB1ENR_GPIOGEN;

  GPIOI->MODER |= (1 << (1 * 2));

  GPIOG->MODER &= ~(3 << (6 * 2));

  while (1) {
    if (!(GPIOG->IDR & (1 << 6))) {
      GPIOI->ODR |= (1 << 1);
    } else {
      GPIOI->ODR &= ~(1 << 1);
    }
    HAL_Delay(50);
  }
}

